%% run_cfu_batch_v41.m — generated by aqua_batch.py (v42 template: overlap 0.3, min events 1, writes _cfu_pre.mat) (mirror of AQuA2's CFU_cmd_batch.m)
% Run from the AQuA2 folder (the script cd's there). For every *_AQuA2.mat of
% the batch it writes next to it: <name>_res_cfu.mat (CFUs), <name>_events.csv
% (one row per event: frames, centre, footprint size and box, peak dF/F, area),
% <name>_eventmap.tif (how many events touched each pixel) and
% <name>_meanimg.tif (mean of the registered movie) — the last three feed the
% activity maps of aqua_analyze.py.
close all; clc; clearvars;
% The AQuA2 copy whose CFU rules are used — normally the copy that detected the events (top row of the GUI).
% The pipeline's CFU definition is AQuA2's published rule: events whose weighted footprints overlap by at
% least the overlap threshold form one unit (single-linkage clustering; cfu.CFU_tmp_function +
% cfu.hierarchicalClusteringMinMeasure). AQuA2 copies from 28 Aug 2026 on add two more rules (watershed
% splitting of every cluster into spatial basins and a post-merge of correlated neighbours); on bouton data
% the splitting triples the unit count and puts one event into several units, so such a copy is used only
% when named explicitly in the GUI (tab 4) — the script says below which rules it is running.
aquaDir = 'H:\MATLAB\AQuA2';
if ~isfolder(aquaDir)                      % the folder set in the GUI is not visible here: find AQuA2 on the MATLAB path
    w = which('aqua_cmd_batch');
    if ~isempty(w), aquaDir = fileparts(w); else, error('AQuA2 not found: set the AQuA2 folder in the GUI (top row) or addpath it in MATLAB'); end
end
cd(aquaDir);
startup;                                   % puts THIS copy first on the path
% ... and no other copy at all: the +cfu package of another AQuA2 copy on the path (one used for a test earlier
% in this MATLAB session, say) would merge with this one and lend it functions it does not have
others = which('aqua_cmd_batch', '-all');
for k = 1:numel(others)
    d = fileparts(others{k});
    if ~strcmpi(regexprep(d, '[\\/]+$', ''), regexprep(aquaDir, '[\\/]+$', ''))
        warning('off', 'MATLAB:rmpath:DirNotFound'); rmpath(genpath(d));
        fprintf('another AQuA2 copy was on the path and is removed for this run: %s\n', d);
    end
end
hasMerge = ~isempty(which('cfu.mergeSimilarCFUs'));
if hasMerge
    ruleTxt = sprintf(['CFU rules of the AQuA2 release from 28 Aug 2026 on: overlap clustering >= %g, then basin ' ...
        'splitting and post-merge (r >= %g) — NOT the published rule the pipeline is set up for'], 0.3, 0.925);
else
    ruleTxt = sprintf('published AQuA2 CFU rule: overlap clustering, overlap >= %g, min events %d', 0.3, 1);
end
fprintf('AQuA2 copy for the CFU step: %s\n   %s\n', aquaDir, ruleTxt);
pIn = 'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2';
whetherUpdateRes = false;               % do not rewrite the big _AQuA2.mat
whetherOutputCFURes = true;             % write <name>_res_cfu.mat
cfuOpts.cfuDetect.overlapThr1 = 0.3;
cfuOpts.cfuDetect.overlapThr2 = 0.3;
cfuOpts.cfuDetect.minNumEvt1 = 1;
cfuOpts.cfuDetect.minNumEvt2 = 1;
if hasMerge
    % post-merge of duplicate units (AQuA2 GUI 'Post-merge correlation', 0..1; 0.5 = AQuA2's default = curves must
    % correlate at r >= 0.925; 0 = r >= 0.85, the most permissive AQuA2 allows). Only set for a copy that has it, so
    % that the cfuOpts saved with a result say which rules made it.
    cfuOpts.cfuDetect.postMergeCorrelationControl = 0.5;
    cfuOpts.cfuDetect.postMergeCorrelationControl2 = 0.5;
    cfuOpts.cfuDetect.minimumCurveCorrelation = 0.925;
    cfuOpts.cfuDetect.minimumCurveCorrelation2 = 0.925;
end
cfuOpts.cfuAnalysis.maxDist = 10;
cfuOpts.cfuAnalysis.shift = 0;
cfuOpts.cfuGroup.pValueThr = 1e-5;
cfuOpts.cfuGroup.cfuNumThr = 3;
% the AQuA2 results of the movies in batch.csv / manifest.json (GUI test
% results elsewhere in the folder are left alone)
resFiles = {
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260915_001\NavRearChrTIGRE-2608-2_260915_001_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260915_003\NavRearChrTIGRE-2608-2_260915_003_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260915_005\NavRearChrTIGRE-2608-2_260915_005_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260915_007\NavRearChrTIGRE-2608-2_260915_007_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260915_002\NavRearChrTIGRE-2608-2_260915_002_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260915_004\NavRearChrTIGRE-2608-2_260915_004_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260915_006\NavRearChrTIGRE-2608-2_260915_006_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260915_008\NavRearChrTIGRE-2608-2_260915_008_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260922_001\NavRearChrTIGRE-2608-2_260922_001_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260922_003\NavRearChrTIGRE-2608-2_260922_003_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260922_005\NavRearChrTIGRE-2608-2_260922_005_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260922_007\NavRearChrTIGRE-2608-2_260922_007_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260922_002\NavRearChrTIGRE-2608-2_260922_002_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260922_004\NavRearChrTIGRE-2608-2_260922_004_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260922_006\NavRearChrTIGRE-2608-2_260922_006_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_260922_008\NavRearChrTIGRE-2608-2_260922_008_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261001_001\NavRearChrTIGRE-2608-2_261001_001_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261001_003\NavRearChrTIGRE-2608-2_261001_003_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261001_005\NavRearChrTIGRE-2608-2_261001_005_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261001_007\NavRearChrTIGRE-2608-2_261001_007_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261001_002\NavRearChrTIGRE-2608-2_261001_002_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261001_004\NavRearChrTIGRE-2608-2_261001_004_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261001_006\NavRearChrTIGRE-2608-2_261001_006_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261001_008\NavRearChrTIGRE-2608-2_261001_008_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261018_001\NavRearChrTIGRE-2608-2_261018_001_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261018_003\NavRearChrTIGRE-2608-2_261018_003_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261018_005\NavRearChrTIGRE-2608-2_261018_005_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261018_007\NavRearChrTIGRE-2608-2_261018_007_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261018_002\NavRearChrTIGRE-2608-2_261018_002_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261018_004\NavRearChrTIGRE-2608-2_261018_004_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261018_006\NavRearChrTIGRE-2608-2_261018_006_bin31f_1p98s_AQuA2.mat'
    'D:\2photon\Chao\GCAMP_affrerents\NavRearChrTIGRE-2608-2\NavRearChrTIGRE-2608-2_261018_008\NavRearChrTIGRE-2608-2_261018_008_bin31f_1p98s_AQuA2.mat'
};
files = struct('name', {}, 'folder', {});
for k = 1:numel(resFiles)
    [fp, fn, fe] = fileparts(resFiles{k});
    if exist(resFiles{k}, 'file')
        files(end+1) = struct('name', [fn fe], 'folder', fp); %#ok<SAGROW>
    else
        fprintf('not there yet (AQuA2 not run?): %s\n', resFiles{k});
    end
end
fprintf('CFU batch: %d file(s)\n', numel(files));
for xxx = 1:numel(files)
    f1 = files(xxx).name; filepath = files(xxx).folder;
    outName = fullfile(filepath, [f1(1:end-4), '_res_cfu.mat']);
    src = dir(fullfile(filepath, f1));
    if exist(outName, 'file') && ~false && ~false
        old = dir(outName);
        same = old.datenum >= src.datenum;
        % v41: a CFU file made with other CFU rules (another overlap / min events, or by an AQuA2 copy with
        % the other rule set — with or without the post-merge) is redone too
        if same
            try
                o = load(outName, 'cfuOpts'); od = o.cfuOpts.cfuDetect;
                same = od.overlapThr1 == cfuOpts.cfuDetect.overlapThr1 && od.minNumEvt1 == cfuOpts.cfuDetect.minNumEvt1;
                if hasMerge
                    same = same && isfield(od, 'minimumCurveCorrelation') && ...
                        abs(od.minimumCurveCorrelation - cfuOpts.cfuDetect.minimumCurveCorrelation) < 1e-6;
                else
                    same = same && ~isfield(od, 'minimumCurveCorrelation');
                end
            catch
                same = false;
            end
        end
        if same
            fprintf('[%d/%d] up to date (same CFU rules), skipping %s\n', xxx, numel(files), f1); continue;
        end
        fprintf('[%d/%d] AQuA2 result newer than its CFU file, or the CFU rules changed -> redoing %s\n', xxx, numel(files), f1);
    end
    fprintf('[%d/%d] %s\n', xxx, numel(files), fullfile(filepath, f1));
    load(fullfile(filepath, f1), 'res');
    datPro = util.normalize01(mean(single(res.datOrg1), 4));
    H = size(res.datOrg1, 1); W = size(res.datOrg1, 2);
    % --- mean image (always, even with no events: the maps of aqua_analyze.py
    % align runs on it), then per-event locations + event footprint map
    imwrite(uint16(round(mean(single(res.datOrg1), 4))), fullfile(filepath, [f1(1:end-4), '_meanimg.tif']));
    try
        fts = res.fts1;
        nEvt = 0;
        if isstruct(fts) && isfield(fts, 'basic') && isfield(fts.basic, 'area')
            nEvt = numel(fts.basic.area);
        end
        if nEvt == 0
            fprintf('   no events in this result\n');
        end
        ctr = zeros(nEvt, 2); npx = zeros(nEvt, 1); bb = zeros(nEvt, 4);
        t0 = zeros(nEvt, 1); t1 = zeros(nEvt, 1); dffMax = zeros(nEvt, 1); area = zeros(nEvt, 1);
        evtMap = zeros(H, W, 'uint16');
        for k = 1:nEvt
            c = fts.basic.center{k}; ctr(k, :) = c(1:2);
            if isfield(fts.loc, 'xSpa')
                pix = fts.loc.xSpa{k};
            else
                [ih0, iw0, ~, ~] = ind2sub(size(res.datOrg1), res.evt1{k});
                pix = unique(sub2ind([H, W], ih0, iw0));
            end
            npx(k) = numel(pix);
            [ih, iw] = ind2sub([H, W], pix);
            bb(k, :) = [min(ih) max(ih) min(iw) max(iw)];
            evtMap(pix) = evtMap(pix) + 1;
            t0(k) = fts.loc.t0(k); t1(k) = fts.loc.t1(k);
            dffMax(k) = fts.curve.dffMax(k); area(k) = fts.basic.area(k);
        end
        evT = table((1:nEvt)', t0, t1, ctr(:, 1), ctr(:, 2), npx, ...
            bb(:, 1), bb(:, 2), bb(:, 3), bb(:, 4), dffMax, area, ...
            'VariableNames', {'event', 't0_frame', 't1_frame', 'y_px', 'x_px', 'n_pixels', ...
            'y0', 'y1', 'x0', 'x1', 'dff_max', 'area_um2'});
        writetable(evT, fullfile(filepath, [f1(1:end-4), '_events.csv']));
        imwrite(evtMap, fullfile(filepath, [f1(1:end-4), '_eventmap.tif']));
    catch exportErr
        fprintf('   event location export failed for %s: %s\n', f1, exportErr.message);
    end
    % --- v42: AQuA2's own pairwise event overlaps (cfu.CFU_tmp_function, the numbers the clustering uses) and a
    % per-event summary -> <name>_cfu_pre.mat, read by the overlap-threshold check (cfu_overlap_check.py / tab 4).
    % Small (no footprints); never stops the batch.
    try
        nE = numel(res.evt1);
        szv = double(res.opts.sz(:)');
        if numel(szv) < 4, szv = [szv, ones(1, 4 - numel(szv))]; end
        pre = cfu.CFU_tmp_function(res.evt1, true, szv);
        evtC = zeros(nE, 2); evtN = zeros(nE, 1); evtT = zeros(nE, 2); evtW = zeros(nE, 1);
        for k = 1:nE
            [ih, iw, ~] = ind2sub(szv(1:3), double(pre.evtIhw{k}));
            w = double(pre.weightedIhw{k}); w = w(:); ih = ih(:); iw = iw(:);
            evtC(k, :) = [sum(ih .* w) / sum(w), sum(iw .* w) / sum(w)];
            evtN(k) = numel(ih); evtW(k) = sum(w);
            [~, ~, ~, it] = ind2sub(szv, double(res.evt1{k}));
            evtT(k, :) = [min(it), max(it)];
        end
        cfuPre = struct('pairs', double(pre.s_t0), 'centre_yx', evtC, 'n_pixels', evtN, 'weight_sum', evtW, ...
            't0_t1', evtT, 'max_counts', double(pre.maxCounts(:)), 'sz', szv, ...
            'overlap_thr', cfuOpts.cfuDetect.overlapThr1, 'min_num_evt', cfuOpts.cfuDetect.minNumEvt1, ...
            'aqua_dir', aquaDir, 'made', datestr(now, 'yyyy-mm-dd HH:MM'));
        save(fullfile(filepath, [f1(1:end-4), '_cfu_pre.mat']), '-struct', 'cfuPre');
        clear pre evtC evtN evtT evtW cfuPre;
    catch preErr
        fprintf('   overlap table (_cfu_pre.mat) not written for %s: %s\n', f1, preErr.message);
    end
    [cfuInfo1, cfuInfo2] = cfu.CFUdetectScript(res, cfuOpts);
    cfuRelation = cfu.calAllDependencyScript(cfuInfo1, cfuInfo2, cfuOpts);
    cfuGroupInfo = cfu.groupCFUscript(cfuInfo1, cfuInfo2, cfuRelation, cfuOpts);
    if whetherUpdateRes
        res.cfuInfo1 = cfuInfo1; res.cfuInfo2 = cfuInfo2;
        res.cfuRelation = cfuRelation; res.cfuGroupInfo = cfuGroupInfo;
        save(fullfile(filepath, f1), 'res', '-v7.3');
    end
    if whetherOutputCFURes
        save(outName, 'cfuInfo1', 'cfuInfo2', 'cfuRelation', 'cfuGroupInfo', 'cfuOpts', 'datPro');
    end
    clear res;
end
disp('CFU batch done.');
